"""Validate Binary Search Tree — carry an open interval down the tree.

Checking only against the parent is the classic bug; every node has to respect
the bounds inherited from all of its ancestors.

Time: O(n)   Space: O(h)
"""
if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def isValidBST(self, root) -> bool:
        def valid(node, low, high) -> bool:
            if not node:
                return True
            if not (low < node.val < high):
                return False
            return (valid(node.left, low, node.val)
                    and valid(node.right, node.val, high))

        return valid(root, float("-inf"), float("inf"))
